INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('项目','介绍一下你的毕业设计？','我做的是一个电影观影网站，分用户端和管理端。用户端能注册登录、分类浏览、看详情、评论点赞；管理端能维护影片、管评论、看统计。我负责后端的数据分析模块：用 Spring MVC 写统计接口，通过 JDBC 访问 MySQL，把影片总数、用户数、平均评分，还有按评分区间、片长、国家、年份的分组统计算出来，返回 JSON 给前端做图表。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('项目','你负责的模块，表怎么设计的？','一共 10 张表。movies 存影片基本信息（标题、评分、年份、片长、国家），users 存用户，comments/likes/favorites 存互动，genres 和 actors 通过 movie_genres、movie_actors 两个中间表跟影片做多对多。统计主要查 movies 表的 rating、year、duration、country 这几个字段。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('项目','统计数据怎么算的？','用 SQL 聚合：COUNT 算总数、AVG 算平均分，按维度统计就用 GROUP BY 加 CASE WHEN 把评分切成区间、片长切成段，再 GROUP BY 分组；查完在 Java 里组装成统一结构，用 Fastjson 转 JSON 返回。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('项目','项目里遇到最大的困难是什么？怎么解决的？','统计接口一开始没处理空值：有的影片没有评分，AVG 算出来是 null，传回前端图表直接空白。我先看接口返回的 JSON，发现那个字段是 null，然后在 SQL 里用 IFNULL 兜底、在 Java 里也加了判空，才稳定下来。这件事让我养成一个习惯：接口返回前先把边界情况（空值、0、没数据）都想一遍。',NULL,3,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('项目','数据量大了怎么办？','现在只有几十上百条，够用。要真上量，我会先把统计字段加索引，再把聚合尽量下推到 SQL（别在 Java 里循环查），数据再大就加缓存或者做定时统计表。这部分我目前只到「知道方向」，还没实操过。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('项目','接口为什么统一返回 code / msg / data？','前端拿到的结构固定，判断 code 就知道成功还是失败，msg 直接能提示用户，data 里放业务数据，不用每个接口写一套解析逻辑。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('项目','怎么部署的？','Maven 打成 war 包，丢到 Tomcat 的 webapps 下启动，数据库是本地 MySQL。出问题就看 Tomcat 日志和项目日志，按报错行往上找。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('框架','MyBatis 你项目里用过吗？','项目里持久层用的是自己封装的 JDBC BaseDao，没上 MyBatis；MyBatis 是课程学过、做过练习，#{} 预编译、${} 拼接这个我知道，写简单的增删改查没问题，复杂的一对多映射得现查文档。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('框架','Redis / Spring Cloud 用过吗？','课程学过，项目里没用过。Redis 我理解就是内存缓存，常用来存热点数据或者做分布式锁；Spring Cloud 是微服务那一套，注册中心、网关、远程调用。原理我大概清楚，实际搭没搭过。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('综合','能实习多久？能不能出差、加班？','现在就能全职，能一直做到毕业，最长可以按公司需要。出差、加班都能接受，我做过现场调试，跑现场不是问题。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('综合','为什么投我们公司？','我看你们做的是 XX 方向（说点具体的，比如自研系统 / 给企业做项目），我现在会的东西正好能用上；另外我想找一个能真正参与项目、有人带的地方，把基础打扎实。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('综合','你觉得自己最大的缺点是什么？','遇到问题容易一头扎进去自己钻，有时候查半天才想起来问人，效率不高。后来我给自己定了个规矩：卡住半小时就先问，或者先把问题写清楚再说。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('综合','最近在学什么？','在补 SpringBoot，把毕设那套 Spring MVC 的东西往 Boot 上迁移，顺便看 MyBatis 的用法。',NULL,2,'面试归纳');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','== 和 equals 的区别？','== 比较基本类型的值、或引用类型的内存地址；equals 默认也是比地址，但 String、Integer 等类重写了它，改成比内容。所以判内容相等要用 equals，判是不是同一个对象用 ==。','[\"==比地址/值\",\"equals可被重写\",\"String已重写equals\"]',1,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','String、StringBuilder、StringBuffer 的区别？','String 不可变，每次拼接都产生新对象；StringBuilder 可变、非线程安全、速度最快，单线程拼接首选；StringBuffer 可变、方法加了 synchronized，线程安全但更慢。','[\"String不可变\",\"Builder非线程安全\",\"Buffer方法同步\"]',1,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','ArrayList 和 LinkedList 的区别？','ArrayList 底层是数组，随机访问 O(1)，中间插入删除要挪元素；LinkedList 底层是双向链表，插入删除只改指针，但随机访问要遍历 O(n)。绝大多数场景用 ArrayList。','[\"数组vs链表\",\"随机访问vs增删\",\"内存开销\"]',1,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','HashMap 的底层结构？JDK8 做了什么优化？','JDK7 是数组 + 链表；JDK8 改成数组 + 链表 + 红黑树，链表长度到 8 且数组长度 ≥ 64 时转红黑树，查询从 O(n) 降到 O(log n)，另外扩容时不再重算 hash，改成高低位拆分。','[\"数组+链表+红黑树\",\"树化阈值8\",\"扩容高低位\"]',3,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','HashMap 为什么线程不安全？ConcurrentHashMap 怎么保证线程安全？','HashMap 并发 put 可能覆盖数据、扩容时形成死循环（JDK7）。ConcurrentHashMap 在 JDK8 用 CAS + synchronized 锁单个桶头节点，锁粒度比以前的分段锁更细。','[\"并发put覆盖\",\"死循环\",\"CAS+锁桶头\"]',3,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','接口和抽象类的区别？','抽象类可以有构造方法、成员变量和普通方法，只能单继承；接口是行为契约，方法默认 public abstract（JDK8 后可有 default/static 方法），可以多实现。一般优先用接口。','[\"单继承vs多实现\",\"抽象类有状态\",\"接口定契约\"]',1,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','final 关键字有哪三种用法？','修饰类不能被继承，修饰方法不能被重写，修饰变量表示只能赋值一次（引用不可变，但对象内部状态仍可变）。','[\"类不可继承\",\"方法不可重写\",\"变量只赋值一次\"]',1,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','重载和重写的区别？','重载（overload）是同一个类里方法名相同、参数列表不同，编译期就确定调用哪个；重写（override）是子类重新实现父类方法，方法签名要一致，运行期多态。','[\"同类名不同参数\",\"子类改实现\",\"编译期vs运行期\"]',1,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','Java 异常体系？checked 和 unchecked 的区别？','Throwable 下分 Error 和 Exception；Exception 又分受检异常（编译期必须处理，如 IOException）和运行时异常（RuntimeException，如空指针），后者不强制 try-catch。','[\"Throwable分两支\",\"受检必须处理\",\"运行时异常不强制\"]',2,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','线程池的核心参数有哪些？','corePoolSize、maximumPoolSize、keepAliveTime、workQueue、threadFactory、拒绝策略。任务先占核心线程，满了进队列，队列满再扩到最大线程，再满就按拒绝策略处理。','[\"七个参数\",\"核心→队列→最大\",\"拒绝策略\"]',3,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','synchronized 和 Lock 的区别？','synchronized 是 JVM 关键字，自动加锁释放，不可中断、非公平；Lock 是接口（ReentrantLock），要手动 lock/unlock，支持可中断、超时、公平锁和多个条件队列。','[\"关键字vs接口\",\"自动释放vs手动\",\"可中断可超时\"]',2,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','volatile 的作用？','保证可见性和有序性：写操作立刻刷回主内存，读操作强制从主内存读；禁止指令重排。但它不保证原子性，i++ 这种还得加锁或用 AtomicInteger。','[\"可见性\",\"禁止重排\",\"不保证原子性\"]',3,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','JVM 内存区域怎么划分？','线程私有：程序计数器、虚拟机栈、本地方法栈；线程共享：堆、方法区（JDK8 后叫元空间，在本地内存）。对象一般分配在堆上。','[\"私有:栈+计数器\",\"共享:堆+方法区\",\"元空间\"]',3,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','怎么判断对象可以被回收？常见的 GC 算法？','用可达性分析：从 GC Roots 出发找不到的对象就可回收（不是引用计数）。算法有标记-清除、复制、标记-整理，实际是分代收集：新生代用复制，老年代用标记-整理。','[\"可达性分析\",\"GC Roots\",\"分代收集\"]',3,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('Java基础','类加载的过程？什么是双亲委派？','加载 → 验证 → 准备 → 解析 → 初始化。双亲委派是加载类时先交给父加载器，父加载器加载不了才自己加载，避免核心类被篡改、避免重复加载。','[\"五个阶段\",\"先父后子\",\"防止核心类被篡改\"]',3,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('数据库','索引为什么用 B+ 树而不是 B 树？','B+ 树只在叶子节点存数据，非叶子节点只存键，同样大小的页能放更多键、扇出更大，树更矮，磁盘 IO 更少；叶子节点还用链表相连，范围查询直接顺序扫。','[\"非叶子不存数据\",\"扇出大层数少\",\"叶子链表利于范围查\"]',2,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('数据库','聚簇索引和非聚簇索引的区别？','InnoDB 主键索引是聚簇索引，叶子节点直接存整行数据；二级索引叶子存的是主键值，查其他字段要回表（再查一次主键索引）。所以主键要短、要自增。','[\"聚簇存整行\",\"二级索引存主键\",\"需要回表\"]',3,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('数据库','什么情况下索引会失效？','对索引列做函数运算或类型转换、like 以 % 开头、联合索引不满足最左前缀、使用 or 且有一边没索引、is null / is not null 有时失效、数据区分度太低。','[\"函数/隐式转换\",\"左模糊\",\"违反最左前缀\"]',2,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('数据库','事务的 ACID？四种隔离级别分别解决什么问题？','ACID：原子性、一致性、隔离性、持久性。隔离级别：读未提交（啥都不解决）、读已提交（解决脏读）、可重复读（解决不可重复读，MySQL 默认）、串行化（解决幻读，性能最差）。','[\"ACID四要素\",\"RC解决脏读\",\"RR解决不可重复读\"]',3,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('数据库','MVCC 是什么？靠什么实现？','多版本并发控制，让读不加锁也能读到一致性快照。实现靠三样：隐藏字段（事务ID、回滚指针）、undo log 版本链、ReadView 可见性判断。','[\"读不加锁\",\"undo版本链\",\"ReadView\"]',3,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('数据库','left join、inner join、right join 的区别？','inner join 只保留两边都匹配的行；left join 保留左表全部，右表没匹配的补 NULL；right join 反过来。统计类查询常用 left join 保证主表数据不丢。','[\"inner只留匹配\",\"left保左表\",\"补NULL\"]',1,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('数据库','where 和 having 的区别？','where 在分组前过滤行，不能用聚合函数；having 在 group by 之后过滤分组结果，可以用 count/avg 这些聚合函数。','[\"where过滤行\",\"having过滤分组\",\"聚合函数\"]',1,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('数据库','一条 SQL 很慢，你怎么排查？','先开慢查询日志定位语句，再用 explain 看执行计划：有没有走索引、type 是不是 ALL、rows 扫了多少、有没有临时表和 filesort；然后针对性加索引或改写 SQL。','[\"慢查询日志\",\"explain看type/rows\",\"避免全表和filesort\"]',2,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('数据库','数据库三大范式？什么时候会反范式？','1NF 字段不可再分，2NF 非主键字段完全依赖主键，3NF 不依赖其他非主键字段。读多写少、性能优先时会故意冗余字段（反范式），减少 join。','[\"1NF不可分\",\"2NF完全依赖\",\"3NF无传递依赖\"]',2,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('框架','Spring 的 IOC 和 AOP 怎么理解？','IOC 是控制反转，对象的创建和依赖交给容器管理，用构造器注入或 @Autowired 注入；AOP 是面向切面，把日志、事务、权限这些横切逻辑抽出来，用动态代理在方法前后织入。','[\"容器管对象\",\"依赖注入\",\"动态代理织入\"]',2,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('框架','Spring Bean 的生命周期？','实例化 → 属性填充 → 各种 Aware 回调 → BeanPostProcessor 前置 → 初始化方法（@PostConstruct、afterPropertiesSet）→ BeanPostProcessor 后置（AOP 代理在这里生成）→ 使用 → 销毁。','[\"实例化+属性填充\",\"初始化前后置\",\"AOP在后置生成\"]',3,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('框架','SpringMVC 一个请求的处理流程？','请求到 DispatcherServlet → 查 HandlerMapping 找到 Controller → HandlerAdapter 执行 → 返回 ModelAndView → ViewResolver 解析视图 → 渲染响应。前后端分离时最后一步直接写 JSON。','[\"DispatcherServlet\",\"HandlerMapping\",\"ViewResolver\"]',2,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('框架','MyBatis 里 #{} 和 ${} 的区别？','#{} 是预编译占位符，用 PreparedStatement 传参，能防 SQL 注入；${} 是字符串直接拼接，有注入风险，只适合拼表名、排序字段这类不能用占位符的地方。','[\"#预编译防注入\",\"$直接拼接\",\"$只拼表名排序\"]',2,'系统预置');
INSERT INTO question (category,title,answer_standard,key_points,difficulty,source) VALUES ('框架','SpringBoot 自动配置的原理？','启动类上的 @SpringBootApplication 里有 @EnableAutoConfiguration，它通过 AutoConfigurationImportSelector 读取 META-INF/spring.factories（新版本是 AutoConfiguration.imports）里的配置类，配合 @Conditional 按条件装配。','[\"EnableAutoConfiguration\",\"读imports文件\",\"@Conditional条件装配\"]',3,'系统预置');
